create table if not exists public.order_groups (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.profiles(id), status text not null default 'payment_pending' check (status in ('payment_pending','paid','partially_refunded','refunded','cancelled','exception')), idempotency_key text not null unique, delivery_address jsonb not null, payable_kobo integer not null check (payable_kobo >= 0), currency text not null default 'NGN', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_group_id uuid not null references public.order_groups(id) on delete cascade, merchant_id uuid not null references public.merchants(id), store_id uuid not null references public.stores(id), status text not null default 'payment_pending' check (status in ('payment_pending','paid','merchant_pending','accepted','preparing','ready_for_pickup','rider_assigned','picked_up','in_transit','delivered','cancelled','refund_pending','refunded','exception')), subtotal_kobo integer not null check (subtotal_kobo >= 0), merchant_allocation_kobo integer not null default 0 check (merchant_allocation_kobo >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(order_group_id, merchant_id));
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid not null references public.products(id), name_snapshot text not null, unit_price_kobo integer not null check (unit_price_kobo >= 0), quantity integer not null check (quantity > 0), total_kobo integer not null check (total_kobo >= 0), created_at timestamptz not null default now());
create table if not exists public.order_events (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id) on delete cascade, order_group_id uuid references public.order_groups(id) on delete cascade, from_status text, to_status text not null, actor_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check (order_id is not null or order_group_id is not null));
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), order_group_id uuid not null references public.order_groups(id) on delete cascade, provider text not null default 'paystack', reference text not null unique, access_code text, amount_kobo integer not null check (amount_kobo >= 0), currency text not null default 'NGN', status text not null default 'initialized' check (status in ('initialized','pending','paid','failed','cancelled','refund_pending','refunded','reversed')), idempotency_key text not null unique, verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.payment_events (id uuid primary key default gen_random_uuid(), payment_id uuid references public.payments(id) on delete set null, provider_event_id text, event_type text not null, payload jsonb not null default '{}'::jsonb, processed_at timestamptz not null default now(), unique(provider_event_id));
create trigger set_updated before update on public.order_groups for each row execute function public.set_updated_at();
create trigger set_updated before update on public.orders for each row execute function public.set_updated_at();
create trigger set_updated before update on public.payments for each row execute function public.set_updated_at();
create index if not exists orders_group_idx on public.orders(order_group_id);
create index if not exists order_items_order_idx on public.order_items(order_id);
